// Map scraper output to Klyro lead records, chunked by 50.
const places = $input.first().json.results || [];
const records = places.map((p) => ({
  name: p.title || p.name,
  website: p.website || null,
  phone: p.phone || null,
  address: p.address || null,
  city: p.city || null,
  country: p.country || $json.country || 'US',
  category: p.category || null,
  rating: p.rating ?? null,
  reviewCount: p.reviews ?? p.reviewCount ?? null,
  lat: p.latitude ?? p.lat ?? null,
  lng: p.longitude ?? p.lng ?? null,
  placeId: p.place_id || p.placeId || null,
}));
const chunks = [];
for (let i = 0; i < records.length; i += 50) chunks.push(records.slice(i, i + 50));
return chunks.map((c, idx) => ({ json: { method: 'POST', path: '/internal/leads/batch', idempotencyKey: `${$json.id || 'job'}-${idx}`, body: { workspaceId: $env.KLYRO_WORKSPACE_ID, source: 'maps', reference: String($json.id || ''), records: c } } }));
